package ma.autocarnet;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import javax.net.ssl.HttpsURLConnection;import org.json.*;
/** Explicit user-triggered city search and routing. Never reads the vehicle logbook. */
final class ConnectedRoutes {
 static long lastRequest=0;static final Map<String,Cache> cache=new LinkedHashMap<>();
 static final class Cache{final String text;final long at;Cache(String s){text=s;at=System.currentTimeMillis();}}
 static synchronized String get(String url)throws Exception{long now=System.currentTimeMillis();Cache c=cache.get(url);if(c!=null&&now-c.at<900000)return c.text;long pause=1200-(now-lastRequest);if(pause>0)Thread.sleep(pause);lastRequest=System.currentTimeMillis();HttpsURLConnection h=(HttpsURLConnection)new URL(url).openConnection();try{h.setConnectTimeout(10000);h.setReadTimeout(25000);h.setInstanceFollowRedirects(false);h.setRequestProperty("User-Agent","AutoCarnet/3.2 (Android personal car logbook)");h.setRequestProperty("X-Client-Id","ma.autocarnet.radouane");if(h.getResponseCode()!=200)throw new IOException("Service indisponible. Réessayez plus tard.");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=h.getInputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>2000000)throw new IOException("Réponse trop volumineuse");out.write(b,0,n);}}String text=out.toString("UTF-8");if(cache.size()>=50)cache.remove(cache.keySet().iterator().next());cache.put(url,new Cache(text));return text;}finally{h.disconnect();}}
 static String encode(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 static JSONObject search(String query,String country)throws Exception{if(query==null||query.trim().length()<2||query.length()>120||!(country.equals("MA")||country.isEmpty()))throw new IllegalArgumentException();String url="https://photon.komoot.io/api/?q="+encode(query.trim())+"&limit=8&lang=fr&osm_tag=place"+(country.isEmpty()?"":"&countrycode=MA");return places(new JSONObject(get(url)));}
 static JSONObject places(JSONObject response)throws Exception{JSONArray features=response.getJSONArray("features"),out=new JSONArray();for(int i=0;i<features.length()&&out.length()<8;i++){JSONObject f=features.getJSONObject(i),p=f.getJSONObject("properties");JSONArray xy=f.getJSONObject("geometry").getJSONArray("coordinates");double lon=xy.getDouble(0),lat=xy.getDouble(1);if(!ParkingRules.coordinates(lat,lon))continue;String name=p.optString("name",p.optString("city",""));if(name.isEmpty())continue;String label=name+(p.optString("state").isEmpty()?"":" · "+p.optString("state"))+(p.optString("country").isEmpty()?"":" · "+p.optString("country"));out.put(new JSONObject().put("label",label.substring(0,Math.min(300,label.length()))).put("lat",lat).put("lon",lon));}return new JSONObject().put("places",out);}
 static JSONObject payload(double a,double b,double c,double d,boolean national,boolean round)throws Exception{if(!ParkingRules.coordinates(a,b)||!ParkingRules.coordinates(c,d)||(a==c&&b==d))throw new IllegalArgumentException();JSONArray locations=new JSONArray().put(new JSONObject().put("lat",a).put("lon",b)).put(new JSONObject().put("lat",c).put("lon",d));if(round)locations.put(new JSONObject().put("lat",a).put("lon",b));return new JSONObject().put("locations",locations).put("costing","auto").put("units","kilometers").put("language","fr-FR").put("costing_options",new JSONObject().put("auto",new JSONObject().put("use_highways",national?0:1).put("exclude_highways",national).put("use_tolls",national?0:1)));}
 static JSONObject route(double a,double b,double c,double d,boolean national,boolean round)throws Exception{JSONObject response=new JSONObject(get("https://valhalla1.openstreetmap.de/route?json="+encode(payload(a,b,c,d,national,round).toString())));return result(response,national,round);}
 static JSONObject result(JSONObject response,boolean national,boolean round)throws Exception{JSONObject trip=response.getJSONObject("trip"),s=trip.getJSONObject("summary");if(trip.optInt("status",0)!=0||!s.has("has_highway")||national&&s.getBoolean("has_highway"))throw new IOException("Aucun trajet sans autoroute vérifiable. Changez les points ou le mode.");double km=s.getDouble("length"),seconds=s.getDouble("time");if(!Double.isFinite(km)||km<=0||km>100000||!Double.isFinite(seconds)||seconds<0)throw new IOException("Distance invalide");JSONArray legs=trip.getJSONArray("legs");if(legs.length()!=(round?2:1))throw new IOException("Trajet incomplet");double outward=legs.getJSONObject(0).getJSONObject("summary").getDouble("length"),back=round?legs.getJSONObject(1).getJSONObject("summary").getDouble("length"):0;if(!Double.isFinite(outward)||outward<=0||!Double.isFinite(back)||back<0||round&&back==0||Math.abs(km-outward-back)>0.1)throw new IOException("Trajet incomplet");return new JSONObject().put("km",km).put("outKm",outward).put("backKm",back).put("minutes",Math.round(seconds/60)).put("highway",s.getBoolean("has_highway")).put("toll",s.has("has_toll")?s.getBoolean("has_toll"):JSONObject.NULL).put("national",national).put("round",round).put("calculatedAt",System.currentTimeMillis());}
}
